import{_ as s,C as o,o as i,c as l,a2 as a,j as t,a as r,E as d}from"./chunks/framework.Di-jvWLj.js";const f=JSON.parse('{"title":"Multiple Replicas","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/replicas.md","filePath":"deployment/replicas.md","lastUpdated":1792243762000}'),c={name:"deployment/replicas.md"},p={id:"what-still-needs-planned-packages",tabindex:"-1"};function h(u,e,g,m,y,k){const n=o("Badge");return i(),l("div",null,[e[3]||(e[3]=a('<h1 id="multiple-replicas" tabindex="-1">Multiple Replicas <a class="header-anchor" href="#multiple-replicas" aria-label="Permalink to &quot;Multiple Replicas&quot;">​</a></h1><p>Running more than one replica of an agent app relies on the store. Part of this works in core today; part needs planned packages.</p><h2 id="what-core-already-guarantees" tabindex="-1">What core already guarantees <a class="header-anchor" href="#what-core-already-guarantees" aria-label="Permalink to &quot;What core already guarantees&quot;">​</a></h2><p>With a shared, durable store, several <code>RunEngine</code>s coordinate without a leader:</p><ul><li><strong>One executor per run.</strong> Run claims are leases (<code>claimTtlMs</code>, renewed every third of it). A replica that loses its lease stops writing.</li><li><strong>One run per concurrency key.</strong> Checked under a store lock, across replicas.</li><li><strong>One run per idempotency key.</strong> <code>dispatch()</code> claims the key atomically; redeliveries to any replica return the same run.</li><li><strong>Crash recovery.</strong> Every replica&#39;s poll requeues runs whose claim expired, and the next execution continues from the latest checkpoint.</li><li><strong>Graceful drain.</strong> A terminating pod marks its unfinished runs <code>interrupted</code> and another replica picks them up.</li><li><strong>Cross-replica cancel.</strong> <code>cancel()</code> on any replica reaches the run&#39;s owner on its next poll.</li><li><strong>One approval notification.</strong> A store lock per approval plus the notifier&#39;s idempotency key.</li></ul><p>Give each replica a distinct <code>owner</code> (the default <code>&lt;hostname&gt;-&lt;pid&gt;</code> already is in Kubernetes). See <a href="/guide/concurrency">Concurrency, Leases &amp; Multi-Replica</a>.</p>',6)),t("h2",p,[e[0]||(e[0]=r("What still needs planned packages ",-1)),d(n,{type:"warning",text:"Planned"}),e[1]||(e[1]=r()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#what-still-needs-planned-packages","aria-label":'Permalink to "What still needs planned packages <Badge type="warning" text="Planned" />"'},"​",-1))]),e[4]||(e[4]=a('<ul><li><strong>A shared store.</strong> <code>MemoryStore</code> cannot be shared. The planned <a href="/stores/typeorm">Postgres store</a> is the first that can.</li><li><strong>Cron once per tick.</strong> The planned scheduler takes a store lock per trigger and scheduled time (never released, so a late replica cannot fire the same tick again) and dispatches with an idempotency key built from the same pair.</li><li><strong>Webhooks to any replica.</strong> The planned HTTP app acknowledges webhooks with <code>202</code> and the run id, and uses the delivery id as the idempotency key, so a redelivery to another replica is deduplicated.</li></ul><p>The planned Helm chart defaults to one replica with the <code>Recreate</code> strategy. Raising the replica count is safe once the store is shared.</p>',2))])}const T=s(c,[["render",h]]);export{f as __pageData,T as default};
